// Remplace les 4 valeurs ci-dessous, puis enregistre le workflow.
// Ne colle jamais ces valeurs réelles dans un fichier versionné (Git) :
// si tu réexportes ce workflow, retire-les d'abord.
const config = {
  supabaseUrl: 'A_COMPLETER', // ex. https://xxxxxxxx.supabase.co
  supabaseServiceKey: 'A_COMPLETER', // clé service_role, PAS anon
  falKey: 'A_COMPLETER', // clé API fal.ai
  falModelEndpoint: 'A_COMPLETER', // slug du modèle, ex. fal-ai/xxx
};
return [{ json: { body: $json.body, config } }];

const action = $('Webhook').item.json.body?.action;
const horsLot = ['correct', 'regenerate', 'validate', 'get_dossier'];
const message = horsLot.includes(action)
  ? `L'action « ${action} » n'est pas encore disponible dans cette version.`
  : `Action inconnue : « ${action ?? 'absente'} ».`;
return [{ json: { erreur: { code: 'action_indisponible', message } } }];

const categories = ['toiture', 'facade', 'volets', 'menuiseries', 'margelles', 'plage'];
const groupes = Object.fromEntries(categories.map((c) => [c, []]));
for (const item of $input.all()) {
  const ligne = item.json;
  if (groupes[ligne.categorie]) {
    groupes[ligne.categorie].push({ id: ligne.id, terme: ligne.terme });
  }
}
return [{ json: { materiaux: groupes } }];

const body = $json.body ?? {};
const erreurs = [];
if (!body.reference || typeof body.reference !== 'string' || body.reference.trim() === '') {
  erreurs.push('la référence du dossier est manquante');
}
if (!body.images || !body.images.cadrage) {
  erreurs.push('la vue de cadrage est manquante');
}
if (!body.style) {
  erreurs.push('le style de rendu est manquant');
}
return [{ json: { valide: erreurs.length === 0, erreurs } }];

const erreurs = $json.erreurs ?? [];
return [{
  json: {
    erreur: {
      code: 'requete_invalide',
      message: `La demande de génération est incomplète : ${erreurs.join(', ')}.`,
    },
  },
}];

const requete = $('Webhook').item.json.body;
const categories = ['toiture', 'facade', 'volets', 'menuiseries', 'margelles', 'plage'];
const ids = [];
for (const c of categories) {
  const selection = requete.materiaux ? requete.materiaux[c] : null;
  if (selection && selection.origine === 'catalogue' && selection.id) ids.push(selection.id);
}
return [{ json: { idsCatalogue: ids } }];

// ---------------------------------------------------------------------------
// SYSTÈME et STYLE : texte calibré repris tel quel du workflow V1
// (« Générateur de Rendu Archi - Evariste », n8n), en anglais dans le texte
// d'origine — non traduit intentionnellement (cf. docs/n8n-setup.md).
// MODE_PRODUCTION reste un brouillon : concept propre à V2, sans équivalent
// direct en V1, à calibrer sur un dossier réel avant mise en production.
// ---------------------------------------------------------------------------

const SYSTEME = `You are given two reference images. Identify their roles by content, not by upload order: one image is a 3D architectural render or CGI visualization — recognizable by clean synthetic lighting, uniform materials, and a computer-generated look. That image is the fixed geometric reference: preserve its building volumes, proportions, roof shape, and camera framing exactly. The other image is a real photograph of the actual site — recognizable by natural lighting, real textures, grain, and photographic imperfections. That image is the fixed environmental reference: preserve its real vegetation, neighboring structures, sky, and light conditions exactly as shown, never substituting an invented or generic setting. If only one image is a 3D render and no real photograph is provided, treat the render alone as the sole geometric and compositional reference.  STRICT ARCHITECTURAL PRESERVATION — NON-NEGOTIABLE, APPLIES TO EVERY REQUEST Use the 3D render image identified above — never the real photograph — as the fixed geometric and compositional reference. Do not modify, reinterpret, add, or remove: building volumes, roof shape and pitch, façade proportions, windows, doors, shutters, balconies, railings, pool shape and position, terrace layout, camera angle, framing, or perspective. Do not invent any architectural element, building, wall, fence, path, furniture, vehicle, or vegetation absent from either reference image. The camera position, angle, and framing are fixed to exactly match the first image: same distance, same angle, same extent of the building visible within the frame. Do not zoom out, reposition the camera, or reveal more of the building, its wings, or its floors than what the first image actually shows. Every part of the building visible in the first image — including balconies, doors, stone base, and all other architectural elements — must remain visible at the same position and scale in the output. Any area within this same frame that is empty, blank, or unrendered in the first image — sky, background, surroundings — is not part of the building and must be filled with the real environment shown in the second image (sky, vegetation, neighboring structures, light), never left blank and never filled with additional invented building elements. Filling these areas must never come at the cost of cropping, shrinking, or omitting any part of the building itself.  PHOTOGRAPHIC REALISM This preservation rule applies to geometry only. The rendering style itself must be fully transformed: completely replace the source render's CGI shading, flat synthetic materials, and studio-clean lighting with the qualities of a real photograph. A light filter or subtle enhancement over the original render is not acceptable — the surface treatment and light behavior must read as an actual photograph, not an improved 3D render. Produce output indistinguishable from a single real photograph. Never treat this as a "3D" or "render" task. The entire image — building and environment alike — must read as one single capture: same light direction, same shadows, same color temperature, same grain level throughout. No surface may appear smoother or more synthetic than the rest of the image. Natural photographic grain and depth of field consistent with a real lens. Natural contrast and tonal depth throughout: believable falloff from sunlit to shaded areas, soft-edged cast shadows, real depth between foreground and background. Never a flat, evenly-lit "product render" look. This is not the same as HDR or tone-mapped high-contrast style — keep contrast natural and photographic, never dramatic, oversaturated, or artificially punchy. Materials show natural tonal variation, never a uniform or plastic surface. Exterior wall render (stucco, plaster, or paint finish) shows visible surface grain, subtle patina, and natural tonal variation from weathering and light — never a flat, uniformly smooth 3D-model finish. Roof tiles show individual tile-to-tile variation in tone and slight surface irregularity, with visible texture at close range — never a single repeated flat color block. Painted shutters, window frames, and joinery show real paint texture, subtle wear, and material grain — never a flat vector-like color fill. This texture requirement applies even though the color and material identity of these elements — their hue, their material type — must stay exactly as in the reference: preserving what a surface is made of is not the same as preserving how smooth or synthetic it currently looks. Exposure on white and light-colored surfaces (façades, renders, trims) retains visible texture and subtle tonal gradation in every zone — never blown out to a flat, detail-less white. Default white balance is neutral daylight color temperature unless a specific time of day or lighting mood is explicitly requested — never a warm yellow or amber cast on surfaces that are actually white or light-grey. Low vegetation and lawn read as an actual photographed lawn, not a textured surface: grass blades have real three-dimensional structure, length, and volume, growing in slightly varied natural directions rather than a uniform combed or brushed pattern, with tiny soft shadows visible between individual blades at close range. The result must look like living grass growing from soil — never a flat printed pattern, a carpet-like weave, or a repeating texture applied to a flat green surface. Subtle tonal variation within a healthy green range — never patchy, blotchy, or showing large tan or brown discoloration either. Sky is a real photographic sky consistent with the lighting condition: natural cloud texture and atmospheric depth — never a flat gradient or synthetic backdrop. Water surfaces (pools, ponds) show realistic reflections, subtle surface ripples, and light refraction consistent with the surrounding light — never a flat, uniform, saturated color fill. Roof fascia boards, bargeboards, and soffits show the same paint texture, material grain, and subtle weathering as the rest of the building envelope — matching sheen and tonal variation with neighboring surfaces. Never a flat, single, untextured color fill on these elements, regardless of how small or secondary they appear in the frame.  CAMERA AND LENS Preserve the original viewpoint and framing exactly — same distance, same angle, same extent of the building within the frame. Do not reframe, zoom out, or extend the shot to show more of the building than the first image contains. Areas of the frame not occupied by the building are filled with real environment per the rule above, never left blank. Neutral 35-50mm architectural lens, no added distortion. Subtle depth of field. Physically accurate exposure with real dynamic range between highlights and shadows. Chromatic aberration kept extremely subtle. Natural lens imperfections. Realistic reflections on windows, with soft interior darkness behind the glazing.  QUALITY No CGI look. No plastic materials. No cartoonish lighting. No exaggerated lens effects.`;

const MODE_PRODUCTION = {
  photomontage_controle: "Intègre le projet directement sur la photographie du site fournie, en respectant exactement son point de vue, sa perspective et sa lumière d'origine. Les zones de la vue de cadrage sans contenu défini sont complétées par le contenu réel visible sur la photographie du site, jamais par un décor inventé ; un ciel seul reste acceptable en l'absence de tout élément environnant visible.",
  presentation_generative: "Présente le projet dans un environnement cohérent inspiré de la photographie du site, sans chercher un alignement géométrique strict avec celle-ci : la photographie sert de référence de matières, de végétation et d'ambiance, pas de calque d'intégration.",
  retexturation_revit: "Aucune photographie du site n'est fournie. Complète les zones vides de la vue de cadrage par un environnement extérieur plausible et sobre, cohérent avec le projet, sans effet de composition ni décor remarquable.",
};

const STYLE = {
  photomontage_administratif: {
    intro: "ADMINISTRATIVE PHOTOMONTAGE STYLE — applies only when Photomontage administratif style is selected. Materials read as credible, believable photographic materials — natural tonal variation, no plastic or synthetic look — but treated with restraint: a light, discreet realism upgrade over the native Revit render, never the rich, close-up photographic detail used for a client presentation. The result should stay recognizably close to a polished Revit render, just made believable. Lawn and low vegetation: individually visible blades, subtle tonal variation within a uniform healthy green range — never patchy, blotchy, or showing large tan or brown discoloration. DEPTH: perfectly uniform sharpness across the entire image, foreground to background, including the neighboring context. Nothing may be softened or blurred — every visible element must remain independently verifiable. LIGHT: neutral, even natural light matching the provided site photograph exactly. No added warmth, no stylization, no artistic treatment.",
    suite: "",
  },
  presentation_client: {
    intro: "CLIENT PRESENTATION STYLE — applies only when Présentation client style is selected. Render every surface as if captured in a close-up real photograph, not as an enhanced 3D render. This applies equally to every material in the frame — roof tiles, rendered facade, stonework, joinery, paving, and low vegetation all receive the same tactile, close-up photographic detail. No single surface may look smoother, flatter, or more synthetic than the others. MATERIALS: rendered facade shows visible fine plaster grain, subtle natural tonal variation, no flat uniform color field; roof tiles show individual tile variation in tone and weathering, visible joints, no repeating pattern; stonework shows visible individual stones, natural color and texture variation, real shadow occlusion between stones; paving shows natural micro-imperfections, believable joints, no plastic sheen. Lawn and low vegetation: individually visible blades, subtle tonal variation within a uniform healthy green range — never patchy, blotchy, or showing large tan or brown discoloration. LIGHT: warm, directional natural light, noticeably warmer and softer than a neutral midday photograph — never a dramatic sunset. DEPTH: natural photographic depth of field, a slight, believable softening of the far background only — the building itself, the pool, and any element of the project stay fully sharp and richly detailed. SKY: clear, bright sky with slightly deeper natural color than a flat neutral midday photo.",
    suite: "",
  },
  commercial: {
    intro: "COMMERCIAL STYLE — applies only when Commercial style is selected. Produce a premium, editorial-quality architectural photograph, in the register of high-end real estate and residential architecture photography. LIGHTING QUALITY: directional, sculpted lighting that reveals the depth and texture of volumes and materials rather than flat frontal illumination; physically accurate global illumination, realistic ambient occlusion, controlled highlights, detailed and well-defined shadows, natural light falloff; elegant tonal range with no crushed blacks and no blown highlights; marked but controlled contrast. Lawn and low vegetation: individually visible blades, subtle tonal variation within a uniform healthy green range — never patchy, blotchy, or showing large tan or brown discoloration. MATERIALS AND FINISH: rich, deep color grading close to professional editorial photography; fine surface micro-detail across the whole image; realistic, refined reflections and light caustics on the pool water and any glazed surface; sophisticated, aspirational, but believable — never plastic, never oversaturated, never cartoonish.",
    suite: "",
  },
};

// Fragments ci-dessous copiés tels quels depuis docs/fragments-prompt.md — ne
// pas les reformuler ailleurs que dans ce fichier source.
const CIEL = {
  reprendre_photo: "La lumière, la direction du soleil, la douceur des ombres et la température de couleur sont reprises exactement de la photographie du site. Les ombres portées des éléments projetés tombent dans la même direction, avec la même longueur et la même densité que celles déjà visibles sur la photographie. Le ciel est celui de la photographie, avec sa texture nuageuse et sa profondeur atmosphérique propres. L'image entière doit paraître capturée en une seule prise de vue : même grain, même contraste, même dominante colorée du premier plan jusqu'à l'horizon.",
  degage: "Ciel bleu franc et dégagé, plus soutenu au zénith et s'éclaircissant progressivement vers l'horizon, avec une profondeur atmosphérique perceptible. Soleil haut, lumière directe : ombres portées nettes, aux bords légèrement adoucis à mesure qu'elles s'éloignent de l'objet qui les projette, densité soutenue conservant du détail dans les zones sombres. Les surfaces claires gardent leur texture et leur gradation tonale sur toute leur étendue. Température de couleur neutre de plein jour.",
  legerement_voile: "Ciel couvert d'un voile de nuages hauts et fins, laissant deviner la position du soleil sans disque nettement dessiné. Lumière directionnelle mais adoucie : les ombres portées restent lisibles, avec des bords diffus et une densité modérée. Contraste doux, gradation fine sur les surfaces courbes et sur le grain des enduits. Température de couleur neutre, très légèrement froide.",
  neutre_diffus: "Lumière naturelle neutre et diffuse de ciel uniformément couvert. Aucune direction dominante : les ombres sont courtes et très douces, essentiellement des ombres de contact au pied des volumes, sous les débords de toiture et dans les feuillures des ouvertures. Ciel clair et uniformément lumineux, conservant une légère texture nuageuse. Contraste faible mais tonalité pleine, chaque matériau restant lisible dans son relief et sa texture propre.",
  fin_de_journee: "Fin d'après-midi, soleil bas sur l'horizon. Lumière rasante et chaude, ambrée sans excès, qui révèle le relief des enduits, des tuiles et des pierres et allonge les ombres portées dans une direction unique et cohérente. Les façades exposées reçoivent une lumière dorée ; les façades opposées basculent dans une ombre légèrement bleutée, éclairée par la seule lumière du ciel. Ciel en dégradé, du bleu profond au zénith vers des tons chauds près de l'horizon, avec une texture nuageuse réelle. Contraste marqué, conservant du détail dans les hautes lumières comme dans les ombres.",
  crepuscule: "Crépuscule, peu après le coucher du soleil. Le ciel conserve une luminosité résiduelle et se dégrade du bleu profond au zénith vers des tons orangés puis violacés près de l'horizon, avec une texture nuageuse réelle. Plus aucune lumière solaire directe : l'éclairage extérieur provient uniquement de la voûte céleste, doux et enveloppant, et des sources artificielles allumées. Les façades prennent une tonalité bleutée froide qui contraste avec la chaleur des éclairages. Équilibre d'exposition d'une photographie d'architecture à l'heure bleue : le ciel reste lisible, les zones éclairées ne sont pas brûlées, les zones sombres conservent leur détail.",
};

const ECLAIRAGES = {
  margelles: "Éclairage linéaire encastré en périphérie du bassin, sous le nez des margelles : lumière chaude et rasante qui souligne le tracé de la piscine et révèle la texture de la pierre en lumière frisante. Intensité discrète, sans halo débordant ni source visible.",
  sous_marin: "Projecteurs immergés dans le bassin, lumière blanche légèrement froide diffusée dans la masse d'eau. L'eau devient translucide et lumineuse de l'intérieur, laissant voir le fond et les parois du bassin. Reflets ondulants portés sur les margelles et sur les surfaces claires les plus proches.",
  appliques_facade: "Appliques murales allumées en façade, lumière chaude dirigée vers le haut et vers le bas, dessinant des cônes lumineux doux sur l'enduit et révélant son grain en lumière rasante. Halos contenus, dégradé progressif jusqu'à l'ombre, sans surexposition autour des sources.",
  interieur_visible: "Éclairage intérieur allumé, visible à travers les baies et les fenêtres : lumière chaude, plus dense que l'ambiance extérieure, laissant deviner la profondeur des pièces sans en détailler le contenu. Les vitrages passent d'un aspect sombre et réfléchissant à une transparence lumineuse.",
};

const PELOUSE = {
  telle_quelle: "La pelouse et la végétation basse sont reprises fidèlement de la photographie du site : même hauteur d'herbe, même densité, mêmes nuances d'une zone à l'autre, y compris les irrégularités présentes.",
  tondue_soignee: "Pelouse récemment tondue et régulièrement entretenue. Les brins d'herbe sont individuellement visibles, dressés avec une orientation naturellement variée, de hauteur régulière, avec de petites ombres douces entre eux à courte distance. Vert sain et homogène, dont les variations de ton d'une zone à l'autre restent légères et contenues. Couverture continue et dense jusqu'aux bordures.",
  fleurie: "Pelouse d'agrément légèrement fleurie, dans le registre de la prairie entretenue. Les brins d'herbe restent individuellement visibles, de hauteur régulière, dans un vert sain dont les variations de ton restent contenues. Quelques marguerites et petites fleurs blanches et jaunes émergent au-dessus de l'herbe, dispersées en petits groupes irréguliers plutôt qu'en semis uniforme. L'ensemble reste manifestement entretenu.",
};

const LABELS_CATEGORIE = {
  toiture: 'toiture',
  facade: 'façade',
  volets: 'volets',
  menuiseries: 'menuiseries',
  margelles: 'margelles',
  plage: 'plage de piscine',
};

// ---------------------------------------------------------------------------
// Assemblage — logique tirée de docs/contrat-webhook-n8n.md et
// docs/fragments-prompt.md §2 (précédence ciel / bloc de style).
// ---------------------------------------------------------------------------

const requete = $('Webhook').item.json.body;
const fragmentsRows = $input.all().map((i) => i.json);
const fragmentsParId = Object.fromEntries(fragmentsRows.map((r) => [r.id, r.fragment_prompt]));

const sections = [];
sections.push(['SYSTÈME', SYSTEME]);
sections.push(['MODE DE PRODUCTION', MODE_PRODUCTION[requete.mode_production] ?? '']);

// Style + lumière : le fragment de ciel remplace toujours le paragraphe
// lumière du bloc de style (docs/fragments-prompt.md §2). Un seul bloc de
// style par appel, jamais deux blocs parlant de lumière.
const styleBloc = STYLE[requete.style];
if (styleBloc) {
  sections.push(['STYLE', [styleBloc.intro, styleBloc.suite].join(' ')]);
}
const cielFragment = CIEL[requete.environnement?.ciel];
if (cielFragment) {
  sections.push(['LUMIÈRE ET AMBIANCE', cielFragment]);
}

// Éclairages : uniquement si la question a été posée (objet non nul).
const eclairages = requete.environnement?.eclairages;
if (eclairages) {
  const allumes = Object.entries(eclairages)
    .filter(([, actif]) => actif === true)
    .map(([cle]) => ECLAIRAGES[cle])
    .filter(Boolean);
  if (allumes.length > 0) {
    sections.push(['ÉCLAIRAGES ALLUMÉS', allumes.join(' ')]);
  }
}

// Matériaux — jamais de matériau_libre ici, uniquement catalogue/existant.
const categories = ['toiture', 'facade', 'volets', 'menuiseries', 'margelles', 'plage'];
const materiauxTexte = [];
for (const c of categories) {
  const selection = requete.materiaux ? requete.materiaux[c] : null;
  if (!selection) continue;
  const label = LABELS_CATEGORIE[c];
  if (selection.origine === 'catalogue') {
    const fragment = fragmentsParId[selection.id];
    if (fragment) {
      materiauxTexte.push(`${label} : ${fragment}.`);
    } else {
      // Aucune invention (PRD §6.1) : on signale plutôt que d'improviser.
      materiauxTexte.push(`${label} : matériau non calibré (« ${selection.terme} »), aucune instruction de matière fournie — ne pas interpréter.`);
    }
  } else if (selection.origine === 'existant') {
    materiauxTexte.push(`${label} : reprends exactement l'aspect visible sur la photographie du site pour cet élément, sans réinterprétation ni remplacement.`);
  }
}
if (materiauxTexte.length > 0) {
  sections.push(['MATÉRIAUX', materiauxTexte.join(' ')]);
}

// Environnement.
const environnementTexte = [];
if (requete.environnement?.conserver_vegetation) {
  environnementTexte.push("La végétation existante visible sur la photographie du site est conservée : mêmes essences, même implantation, même volume, avec une variation de couleur bornée et sans aspect irrégulier.");
}
const pelouseFragment = PELOUSE[requete.environnement?.aspect_pelouse];
if (pelouseFragment) environnementTexte.push(pelouseFragment);
const elementsARetirer = (requete.environnement?.elements_a_retirer ?? '').trim();
if (elementsARetirer) {
  environnementTexte.push(`Retire de l'image les éléments suivants, sans modifier ni recomposer le reste de la scène : ${elementsARetirer}.`);
}
if (environnementTexte.length > 0) {
  sections.push(['ENVIRONNEMENT', environnementTexte.join(' ')]);
}

const elementsAPreserver = (requete.elements_a_preserver ?? '').trim();
if (elementsAPreserver) {
  sections.push(['ÉLÉMENTS À PRÉSERVER', `Conserve strictement les éléments suivants tels qu'ils apparaissent sur les vues fournies, sans les réinterpréter : ${elementsAPreserver}.`]);
}

const precisions = (requete.precisions ?? '').trim();
if (precisions) {
  sections.push(['PRÉCISIONS', precisions]);
}

const promptComplet = sections.map(([titre, texte]) => `[${titre}]
${texte}`).join('\n\n');

const imageUrls = [requete.images.cadrage];
if (requete.images.site) imageUrls.push(requete.images.site);

const payloadFal = {
  prompt: promptComplet,
  image_urls: imageUrls,
  aspect_ratio: '4:3',
  resolution: '2K',
  seed: 42,
};

return [{
  json: {
    reference: requete.reference,
    promptComplet,
    payloadFal,
  },
}];

const statut = $input.first().json;
const precedent = $('Attendre').item.json;
return [{
  json: {
    status: statut.status,
    status_url: precedent.status_url,
    response_url: precedent.response_url,
    tentative: (precedent.tentative ?? 0) + 1,
  },
}];

return [{
  json: {
    erreur: {
      code: 'delai_depasse',
      message: "La génération prend trop de temps. Réessaie dans quelques minutes ; si le problème persiste, contacte le support.",
    },
  },
}];

const resultat = $json;
const image = (resultat.images && resultat.images[0]) || resultat.image || null;
return [{
  json: {
    imageExploitable: Boolean(image && image.url),
    imageUrl: image ? image.url : null,
  },
}];

return [{
  json: {
    erreur: {
      code: 'generation_echouee',
      message: "La génération n'a pas produit d'image exploitable. Réessaie ; si le problème persiste, vérifie la configuration fal.ai côté n8n.",
    },
  },
}];

const contexte = $('Construire le prompt').item.json;
const image = $('Évaluer le résultat').item.json;
return [{
  json: {
    reference: contexte.reference,
    statut: 'en_cours',
    cycle_type: 'generation',
    image_url: image.imageUrl,
    prompt: contexte.promptComplet,
    payload: contexte.payloadFal,
  },
}];

const ligne = $json;
return [{
  json: {
    cycle_id: ligne.id,
    reference: ligne.reference,
    image_url: ligne.image_url,
    prompt: ligne.prompt,
  },
}];
